import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.RycU2wFZ.js";const i="/docs/assets/arbiscan-phase1-tx.CBOQAN6F.png",g=JSON.parse('{"title":"10 分钟 Demo","description":"一条命令跑通三个场景：正常付款成功、超额被拒绝、失控循环被熔断","frontmatter":{"title":"10 分钟 Demo","description":"一条命令跑通三个场景：正常付款成功、超额被拒绝、失控循环被熔断"},"headers":[],"relativePath":"zh/learn/05-hands-on/ten-minute-demo.md","filePath":"zh/learn/05-hands-on/ten-minute-demo.md","lastUpdated":1792490239000}'),o={name:"zh/learn/05-hands-on/ten-minute-demo.md"};function l(p,t,d,r,c,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="_10-分钟-demo" tabindex="-1">10 分钟 Demo <a class="header-anchor" href="#_10-分钟-demo" aria-label="Permalink to &quot;10 分钟 Demo&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 尚未经过独立安全审计，请勿用于生产环境的真实资金。本页只使用测试网和测试代币。</p></div><h2 id="你将看到什么" tabindex="-1">你将看到什么 <a class="header-anchor" href="#你将看到什么" aria-label="Permalink to &quot;你将看到什么&quot;">​</a></h2><p>用一个脚本，在一台机器上依次演示三个场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>发生了什么</th><th>防火墙的反应</th></tr></thead><tbody><tr><td><strong>1. 正常付款</strong></td><td>Agent 购买一条 NVDA 行情，价格 $0.05</td><td>放行 → 签名 → 结算，Agent 拿到数据</td></tr><tr><td><strong>2. 超额付款</strong></td><td>Agent 调用一个 $2.50 的重型计算接口</td><td>单笔上限是 $0.10，直接拒绝，<strong>不签名</strong></td></tr><tr><td><strong>3. 失控循环</strong></td><td>Agent 陷入无限调用循环</td><td>每分钟最多 5 次，超过后熔断，后续调用全部被阻断</td></tr></tbody></table><p>Demo 中防火墙的配置是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单笔上限 $0.10  |  24 小时预算 $1.00  |  每分钟最多 5 次</span></span></code></pre></div><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>Python 3.10 或以上、<code>make</code>、<code>git</code></li><li>克隆仓库：</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/july-whj/AgentPay.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AgentPay</span></span></code></pre></div><ul><li>依赖安装请参照仓库 README 的 Quickstart。</li></ul><h2 id="第一步-本地模拟运行-推荐先跑这个" tabindex="-1">第一步：本地模拟运行（推荐先跑这个） <a class="header-anchor" href="#第一步-本地模拟运行-推荐先跑这个" aria-label="Permalink to &quot;第一步：本地模拟运行（推荐先跑这个）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><p>这个模式在本机内存里模拟整条链路，<strong>不联网、不消耗 Gas、不需要测试币</strong>，几秒钟就能跑完，而且每次结果一致。</p><h3 id="阶段一-正常付款" tabindex="-1">阶段一：正常付款 <a class="header-anchor" href="#阶段一-正常付款" aria-label="Permalink to &quot;阶段一：正常付款&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; [PHASE 1] Normal Micro-Payment with On-Chain Settlement &lt;&lt;&lt;</span></span>
<span class="line"><span>Agent requests paid market data for &#39;NVDA&#39; ($0.05 USDC).</span></span>
<span class="line"><span>✓ Tool Response Received: {&#39;ticker&#39;: &#39;NVDA&#39;, &#39;price&#39;: 142.5, ...}</span></span>
<span class="line"><span>[Facilitator] ON_CHAIN_TRANSACTION_CONFIRMED</span></span></code></pre></div><p>Agent 只是调用了一次普通的工具，但背后发生了这些事：</p><ol><li>卖方返回&quot;需要付款&quot;的要求；</li><li>防火墙检查：$0.05 没有超过单笔上限，预算充足 → <strong>放行</strong>；</li><li>本地签名器产生一份离线的转账授权；</li><li>带着授权重新请求，拿到数据；</li><li>Facilitator 把授权提交结算。</li></ol><p>日志里有一行值得注意：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;gasChargedToBuyer&quot;: &quot;0.0000 ETH (Free EIP-3009 Transfer)&quot;</span></span></code></pre></div><p>买方钱包里只需要 USDC，不需要持有 ETH 来付 Gas。（原理见 <a href="./../02-agent-payments/gasless-eip-3009">免 Gas 授权</a>）</p><h3 id="阶段二-超出单笔上限" tabindex="-1">阶段二：超出单笔上限 <a class="header-anchor" href="#阶段二-超出单笔上限" aria-label="Permalink to &quot;阶段二：超出单笔上限&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[BuyerFirewall] POLICY_VIOLATION_INTERCEPTED</span></span>
<span class="line"><span>  &quot;errorCode&quot;: &quot;SINGLE_TX_CAP_EXCEEDED&quot;,</span></span>
<span class="line"><span>  &quot;requestedAmountUsdc&quot;: &quot;2.50&quot;,</span></span>
<span class="line"><span>  &quot;maxAllowedPerTxUsdc&quot;: &quot;0.10&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;PAYMENT_ABORTED_SAFELY&quot;,</span></span>
<span class="line"><span>  &quot;walletFundsDrained&quot;: &quot;0.00 USDC&quot;</span></span></code></pre></div><p>请求 $2.50，上限 $0.10，防火墙在<strong>签名之前</strong>就拒绝了。没有签名，就没有任何资金可能离开钱包。</p><p>日志里还有一行 <code>toolObservation</code>，这是防火墙把拒绝原因反馈给 Agent 的内容。Agent 能知道&quot;为什么被拒绝&quot;，可以据此换一个方案，但它没有办法改变规则。</p><h3 id="阶段三-失控循环被熔断" tabindex="-1">阶段三：失控循环被熔断 <a class="header-anchor" href="#阶段三-失控循环被熔断" aria-label="Permalink to &quot;阶段三：失控循环被熔断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[BuyerFirewall] CIRCUIT_BREAKER_TRIPPED</span></span>
<span class="line"><span>  &quot;iteration&quot;: 5,</span></span>
<span class="line"><span>  &quot;breakerState&quot;: &quot;OPEN&quot;,</span></span>
<span class="line"><span>  &quot;reason&quot;: &quot;CIRCUIT_MAX_RPM_EXCEEDED (Max 5 RPM exceeded)&quot;,</span></span>
<span class="line"><span>  &quot;cooldownSeconds&quot;: 300</span></span>
<span class="line"><span>✗ Loop iteration #5 BLOCKED by Circuit Breaker</span></span></code></pre></div><p>Agent 进入死循环，一口气发出 8 次调用。前 4 次正常付款，加上阶段一的那一次，一分钟内的付款达到了 5 次的上限。从第 5 次循环开始，熔断器进入打开状态，后面的调用全部被阻断，冷却时间为 300 秒。</p><p>这就是 <a href="./../04-agentpay-concepts/financial-firewall">为什么需要金融防火墙</a> 里那场&quot;一小时烧掉 1,800 USDC&quot;的循环，被截断在几秒之内。</p><h3 id="最后的审计报告" tabindex="-1">最后的审计报告 <a class="header-anchor" href="#最后的审计报告" aria-label="Permalink to &quot;最后的审计报告&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calls Attempted:             10</span></span>
<span class="line"><span>Successful Paid Calls:       5</span></span>
<span class="line"><span>Over-Budget Blocks:          1</span></span>
<span class="line"><span>Runaway Loop Blocks:         4</span></span>
<span class="line"><span>Total Spend Attempted:       $2.63 USDC</span></span>
<span class="line"><span>Actual Funds Debited:        $0.09 USDC</span></span>
<span class="line"><span>Total Funds Saved by AgentPay: $2.54 USDC</span></span></code></pre></div><p>这几个数字可以这样对上：</p><table tabindex="0"><thead><tr><th>数字</th><th>含义</th></tr></thead><tbody><tr><td>10 次调用</td><td>阶段一 1 次 + 阶段二 1 次 + 阶段三 8 次</td></tr><tr><td>5 次成功付款</td><td>阶段一 1 次 + 循环中前 4 次</td></tr><tr><td>5 次被拦截</td><td>超额 1 次 + 熔断 4 次</td></tr><tr><td>实际扣款 $0.09</td><td>5 次成功付款的合计</td></tr><tr><td>被拦下的 $2.54</td><td>超额的 $2.50 + 被熔断的 4 次调用</td></tr></tbody></table><p>注意：<strong>熔断前已经付出去的 4 次小额付款不会被追回。</strong> 防火墙限制的是损失的上限，而不是让损失为零。</p><h2 id="第二步-可选-真实的链上结算" tabindex="-1">第二步（可选）：真实的链上结算 <a class="header-anchor" href="#第二步-可选-真实的链上结算" aria-label="Permalink to &quot;第二步（可选）：真实的链上结算&quot;">​</a></h2><p>如果你想看到交易真正出现在区块浏览器上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo-live</span></span></code></pre></div><p>这个模式会向 Arbitrum Sepolia 测试网真实广播交易。</p><h3 id="额外的准备" tabindex="-1">额外的准备 <a class="header-anchor" href="#额外的准备" aria-label="Permalink to &quot;额外的准备&quot;">​</a></h3><ul><li><strong>Facilitator 钱包</strong>需要少量 Arbitrum Sepolia 测试网 ETH，用来支付 Gas；</li><li><strong>买方钱包</strong>需要测试网 USDC（Circle 官方测试代币）；</li><li>按 README 配置密钥与 RPC。</li></ul><div class="danger custom-block"><p class="custom-block-title">不要使用公开的密钥</p><p>很多教程和开发工具里的默认示例账户，私钥是<strong>公开已知</strong>的，任何人都能操作这些地址，链上的机器人也会盯着它们。运行 live 模式请<strong>新生成</strong>一对测试密钥，并且只充入测试币。任何示例密钥都<strong>绝对不能</strong>用于主网。</p></div><h3 id="在-arbiscan-上验证" tabindex="-1">在 Arbiscan 上验证 <a class="header-anchor" href="#在-arbiscan-上验证" aria-label="Permalink to &quot;在 Arbiscan 上验证&quot;">​</a></h3><p>运行结束后，阶段一的日志里会有一个真实的交易哈希和 Arbiscan 链接。下面是这次运行的交易页面：</p><p><img src="`+i+`" alt="Arbiscan 上的阶段一交易"></p><p>可以对照这几项来读：</p><table tabindex="0"><thead><tr><th>Arbiscan 字段</th><th>看到的内容</th><th>含义</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Success</td><td>链上执行成功</td></tr><tr><td><strong>ERC-20 Tokens Transferred</strong></td><td>从买方转给收款方，0.05 USDC</td><td>这就是 Agent 付出的钱，与 Demo 里的 $0.05 一致</td></tr><tr><td><strong>From</strong></td><td>Facilitator 钱包地址</td><td>发起交易并<strong>支付 Gas 的是 Facilitator，不是买方</strong></td></tr><tr><td><strong>Transaction Fee</strong></td><td>约 0.0000018 ETH</td><td>这笔 Gas 由 Facilitator 承担，买方为 0</td></tr><tr><td><strong>Value</strong></td><td>0 ETH</td><td>交易本身没有转移 ETH，转移的是 USDC</td></tr><tr><td><strong>Timestamp</strong></td><td>与日志中的时间一致</td><td>可以与终端日志互相印证</td></tr></tbody></table><p>这张图同时证明了一件事：买方通过一份离线签名授权了转账，真正上链的是 Facilitator，买方不需要为 Gas 付一分钱。</p><details class="details custom-block"><summary>实时模式下可能看到的 nonce too low 日志</summary><p>在 live 模式的末尾，后台结算阶段可能出现类似下面的日志：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Failed to broadcast settlement tx: RPC error -32000: nonce too low ...</span></span>
<span class="line"><span>Settlement submission failed ... Facilitator error 409: Nonce has already been submitted for settlement</span></span></code></pre></div><p><code>nonce too low</code> 表示 Facilitator 钱包准备使用的交易序号，已经落后于链上该账户当前的序号。常见原因是同一个钱包同时广播多笔交易，或者这个地址正被其他人或程序同时使用。</p><p>遇到这种情况时，对应的那几笔结算没有成功上链，需要通过对账补发。这也说明了 <a href="./../04-agentpay-concepts/timeout-is-not-failure">超时不等于失败</a> 里的道理：<strong>&quot;提交失败&quot;不等于&quot;这笔付款不存在&quot;，需要查清楚再处理，而不是盲目重发。</strong></p></details><h2 id="验证清单" tabindex="-1">验证清单 <a class="header-anchor" href="#验证清单" aria-label="Permalink to &quot;验证清单&quot;">​</a></h2><p>跑完之后，对照一下你应该看到：</p><ul><li>[ ] 阶段一：拿到了行情数据，日志里 Gas 由买方承担的部分是 0</li><li>[ ] 阶段二：出现 <code>SINGLE_TX_CAP_EXCEEDED</code>，被拒绝的金额没有离开钱包</li><li>[ ] 阶段三：循环从第 5 次开始被熔断，状态为 <code>OPEN</code></li><li>[ ] 报告：被拦下的金额远大于实际扣款</li><li>[ ] （live 模式）阶段一的交易能在 Arbiscan 上查到</li></ul><h2 id="动手改一改" tabindex="-1">动手改一改 <a class="header-anchor" href="#动手改一改" aria-label="Permalink to &quot;动手改一改&quot;">​</a></h2><p>打开 <code>examples/runaway-agent/demo.py</code>，找到防火墙的三个参数（单笔上限、24 小时预算、每分钟次数），试试：</p><ol><li>把单笔上限调大到 $3.00，再运行一次。阶段二还会被拒绝吗？如果被拒绝，拒绝的原因变成了什么？</li><li>把每分钟次数调到 20。熔断会在第几次循环触发？</li><li>把 24 小时预算调到 $0.05，阶段三的结果会怎样？</li></ol><p>每次改完，对照日志里的 <code>errorCode</code> 看是哪一条规则拦住了请求。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想理解防火墙背后的设计：<a href="./../04-agentpay-concepts/financial-firewall">为什么需要金融防火墙</a></li><li>想理解并发下预算为什么不会超支：<a href="./../04-agentpay-concepts/budget-reservation">预算预留</a></li><li>想用 Web 控制台配置网关和策略：<a href="./first-paid-route">在控制台配置第一个付费路由</a></li></ul>`,57)])])}const b=a(o,[["render",l]]);export{g as __pageData,b as default};
